examples.setupTemplate:
var settings by remember {
    mutableStateOf(
        MonarchAiSpendCapSettings(
            limit = {{settings.limit}},
            warnAt = {{settings.warnAt|double}},
            behavior = MonarchAiSpendCapBehavior.{{settings.behaviour|pascal}},
        ),
    )
}
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

examples.setup:
var settings by remember {
    mutableStateOf(
        MonarchAiSpendCapSettings(
            limit = 5000,
            warnAt = 0.8,
            behavior = MonarchAiSpendCapBehavior.Pause,
        ),
    )
}
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-GB")) }
}
